import{_ as a,c as e,o as c,b0 as l}from"./chunks/framework.BWMBvyU7.js";const t="/programming-docs/assets/105TBL5-0-1777983378711-55.DXs0W6pH.jpg",p="/programming-docs/assets/105TC045-1-1777983396329-57.BYCvv18b.jpg",d="/programming-docs/assets/105T63164-2-1777983407041-59.BW-Lycjc.jpg",r="/programming-docs/assets/105T61102-3-1777983426705-61.DfB1qAcG.jpg",s="/programming-docs/assets/105TB2b-4-1777983434057-63.D9l0YM8H.jpg",m="/programming-docs/assets/105TC510-5-1777983456291-65.2wVR7M9M.jpg",b=JSON.parse('{"title":"LV640-malloc的原理简介","description":null,"frontmatter":{"title":"LV640-malloc的原理简介","date":"2026-05-05T20:15:34.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/Language/c/memory/126d44372b7e1d620d1c4da4","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-05-05T20:15:34.470Z","fulluuid":"20d1c4da437b4567aa4a8f4af09bd522","useduuid":"20d1c4da4"}},"headers":[],"relativePath":"sdoc/Language/c/memory/126d44372b7e1d620d1c4da4.md","filePath":"sdoc/01-编程语言/01-C语言/30-内存管理/LV640-malloc的原理简介.md","lastUpdated":1777987950000}'),i={name:"sdoc/Language/c/memory/126d44372b7e1d620d1c4da4.md"};function n(u,o,g,_,h,f){return c(),e("div",null,[...o[0]||(o[0]=[l('<h1 id="lv640-malloc的原理简介" tabindex="-1">LV640-malloc的原理简介 <a class="header-anchor" href="#lv640-malloc的原理简介" aria-label="Permalink to &quot;LV640-malloc的原理简介&quot;">​</a></h1><p>相对于栈而言，堆这片内存面临着一个稍微复杂的行为模式：在任意时刻，程序可能发出请求，要么申请一段内存，要么释放一段已经申请过的内存，而且申请的大小从几个字节到几个 GB 都有可能，我们不能假设程序一次申请多少堆空间，因此，堆的管理显得较为复杂。</p><p>那么，使用 <code>malloc()</code> 在堆上分配内存到底是如何实现的呢？</p><p>一种做法是把 <code>malloc()</code> 的内存管理交给系统内核去做，既然内核管理着进程的地址空间，那么如果它提供一个系统调用，可以让 <code>malloc()</code> 使用这个系统调用去申请内存，不就可以了吗？当然这是一种理论上的做法，但实际上这样做的性能比较差，因为每次程序申请或者释放堆空间都要进行系统调用。我们知道系统调用的性能开销是比较大的，当程序对堆的操作比较频繁时，这样做的结果会严重影响程序的性能。</p><p>比较好的做法就是 <code>malloc()</code> 向操作系统申请一块适当大小的堆空间，然后由 <code>malloc()</code> 自己管理这块空间。</p><p><code>malloc()</code> 相当于向操作系统 &quot;批发&quot; 了一块较大的内存空间，然后 &quot;零售&quot; 给程序用。当全部 &quot;售完&quot; 或程序有大量的内存需求时，再根据实际需求向操作系统 &quot;进货&quot;。当然 <code>malloc()</code> 在向程序零售堆空间时，必须管理它批发来的堆空间，不能把同一块地址出售两次，导致地址的冲突。于是 <code>malloc()</code> 需要一个算法来管理堆空间，这个算法就是堆的分配算法。</p><h2 id="一、-malloc-和-free-的分配算法" tabindex="-1">一、 malloc()和 free()的分配算法 <a class="header-anchor" href="#一、-malloc-和-free-的分配算法" aria-label="Permalink to &quot;一、 malloc()和 free()的分配算法&quot;">​</a></h2><p>在程序运行过程中，堆内存从低地址向高地址连续分配，随着内存的释放，会出现不连续的空闲区域，如下图所示：</p><img src="'+t+'" alt="已分配内存和空闲内存相间出现"><p>图 1：已分配内存和空闲内存相间出现</p><p>带阴影的方框是已被分配的内存，白色方框是空闲内存或已被释放的内存。程序需要内存时，<code>malloc()</code> 首先遍历空闲区域，看是否有大小合适的内存块，如果有，就分配，如果没有，就向操作系统申请（发生系统调用）。为了保证分配给程序的内存的连续性，<code>malloc()</code> 只会在一个空闲区域中分配，而不能将多个空闲区域联合起来。</p><p>内存块（包括已分配和空闲的）的结构类似于链表，它们之间通过指针连接在一起。在实际应用中，一个内存块的结构如下图所示：</p><p><img src="'+p+'" alt="内存块的结构"></p><p>图 2：内存块的结构</p><p>next 是指针，指向下一个内存块，used 用来表示当前内存块是否已被使用。这样，整个堆区就会形成如下图所示的链表：</p><p><img src="'+d+'" alt="类似链表的内存管理方式"></p><p>图 3：类似链表的内存管理方式</p><p>现在假设需要为程序分配 100 个字节的内存，当搜索到图中第一个空闲区域（大小为 200 个字节）时，发现满足条件，那么就在这里分配。这时候 <code>malloc()</code> 会把第一个空闲区域拆分成两部分，一部分交给程序使用，剩下的部分任然空闲，如下图所示：</p><p><img src="'+r+'" alt="为程序分配 100 个字节的内存"></p><p>图 4：为程序分配 100 个字节的内存</p><p>仍然以图 3 为例，当程序释放掉第三个内存块时，就会形成新的空闲区域，<code>free()</code> 会将第二、三、四个连续的空闲区域合并为一个，如下图所示：</p><p><img src="'+s+'" alt="释放第三个内存块"></p><p>图 5：释放第三个内存块</p><p>可以看到，<code>malloc()</code> 和 <code>free()</code> 所做的工作主要是对已有内存块的分拆和合并，并没有频繁地向操作系统申请内存，这大大提高了内存分配的效率。</p><p>另外，由于单向链表只能向一个方向搜索，在合并或拆分内存块时不方便，所以大部分 <code>malloc()</code> 实现都会在内存块中增加一个 pre 指针指向上一个内存块，构成双向链表，如下图所示：</p><p><img src="'+m+'" alt="双向链表的内存块结构"></p><p>链表是一种经典的堆内存管理方式，经常被用在教学中，很多 C 语言教程都会提到 &quot;栈内存的分配类似于数据结构中的栈，而堆内存的分配却类似于数据结构中的链表&quot; 就是源于此。</p><p>链表式内存管理虽然思路简单，容易理解，但存在很多问题，例如：</p><ul><li>一旦链表中的 pre 或 next 指针被破坏，整个堆就无法工作，而这些数据恰恰很容易被越界读写所接触到。</li><li>小的空闲区域往往不容易再次分配，形成很多内存碎片。</li><li>经常分配和释放内存会造成链表过长，增加遍历的时间。</li></ul><p>针对链表的缺点，后来人们提出了位图和对象池的管理方式，而现在的 <code>malloc()</code> 往往采用多种方式复合而成，不同大小的内存块往往采用不同的措施，以保证内存分配的安全和效率。</p><h2 id="二、-内存池" tabindex="-1">二、 内存池 <a class="header-anchor" href="#二、-内存池" aria-label="Permalink to &quot;二、 内存池&quot;">​</a></h2><p>不管具体的分配算法是怎样的，为了减少系统调用，减少物理内存碎片，<code>malloc()</code> 的整体思想是先向操作系统申请一块大小适当的内存，然后自己管理，这就是 <strong>内存池（Memory Pool）</strong>。</p><p>内存池的研究重点不是向操作系统申请内存，而是对已申请到的内存的管理，这涉及到非常复杂的算法，是一个永远也研究不完的课题，除了 C 标准库自带的 <code>malloc()</code>，还有一些第三方的实现，比如 Google 的 tcmalloc 和 jemalloc。</p><p>我们知道，C/C++ 是编译型语言，没有内存回收机制，程序员需要自己释放不需要的内存，这在给程序带来了很大灵活性的同时，也带来了不少风险，例如 C/C++ 程序经常会发生内存泄露，程序刚开始运行时占用内存很少，随着时间的推移，内存使用不断增加，导致整个计算机运行缓慢。</p><p>内存泄露的问题往往难于调试和发现，或者只有在特定条件下才会复现，这给代码修改带来了不少障碍。为了提高程序的稳定性和健壮性，后来的 Java、Python、C#、JavaScript、PHP 等使用了虚拟机机制的非编译型语言都加入了垃圾内存自动回收机制，这样程序员就不需要管理内存了，系统会自动识别不再使用的内存并把它们释放掉，避免内存泄露。可以说，这些高级语言在底层都实现了自己的内存池，也即有自己的内存管理机制。</p><h2 id="三、-池化技术" tabindex="-1">三、 池化技术 <a class="header-anchor" href="#三、-池化技术" aria-label="Permalink to &quot;三、 池化技术&quot;">​</a></h2><p>在计算机中，有很多使用 &quot;池&quot; 这种技术的地方，除了内存池，还有连接池、线程池、对象池等。以服务器上的线程池为例，它的主要思想是：先启动若干数量的线程，让它们处于睡眠状态，当接收到客户端的请求时，唤醒池中某个睡眠的线程，让它来处理客户端的请求，当处理完这个请求，线程又进入睡眠状态。</p><p>所谓 &quot;池化技术&quot;，就是程序先向系统申请过量的资源，然后自己管理，以备不时之需。之所以要申请过量的资源，是因为每次申请该资源都有较大的开销，不如提前申请好了，这样使用时就会变得非常快捷，大大提高程序运行效率。</p><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',40)])])}const T=a(i,[["render",n]]);export{b as __pageData,T as default};
